<span class="line"><span style="color:#D73A49;">  const</span><span style="color:#005CC5;"> expr</span><span style="color:#D73A49;"> =</span><span style="color:#032F62;"> /&lt;%(</span><span style="color:#005CC5;">[\\s\\S]</span><span style="color:#D73A49;">+?</span><span style="color:#032F62;">)%&gt;/</span><span style="color:#D73A49;">g</span><span style="color:#24292E;">;</span></span>
